import { initializeApp, getApps, getApp } from 'firebase/app';
import {
  getAuth,
  GoogleAuthProvider,
  signInWithPopup,
  signOut as firebaseSignOut,
  onAuthStateChanged,
  type User
} from 'firebase/auth';
import {
  getFirestore,
  initializeFirestore,
  doc,
  setDoc,
  getDoc,
  getDocs,
  collection,
  query,
  where,
  getDocFromServer,
  type Firestore,
  type FirestoreSettings
} from 'firebase/firestore';

// Import configuration generated by Firebase Provisioning
import firebaseConfig from '../firebase-applet-config.json';

// Initialize Firebase App
const app = !getApps().length ? initializeApp(firebaseConfig) : getApp();

// Authentication and Firestore instances
// Disable experimental fetch streams & force long-polling so WebChannel uses native XHR
// instead of Fetch AbortController streams that emit AbortError inside iframe/proxy environments.
const firestoreSettings = {
  experimentalForceLongPolling: true,
  useFetchStreams: false
} as FirestoreSettings;

function createFirestoreInstance(): Firestore {
  const databaseId = firebaseConfig.firestoreDatabaseId || undefined;
  try {
    return initializeFirestore(app, firestoreSettings, databaseId);
  } catch {
    return databaseId ? getFirestore(app, databaseId) : getFirestore(app);
  }
}

export const auth = getAuth(app);
export const db = createFirestoreInstance();
export const googleProvider = new GoogleAuthProvider();
googleProvider.setCustomParameters({ prompt: 'select_account' });

export enum OperationType {
  CREATE = 'create',
  UPDATE = 'update',
  DELETE = 'delete',
  LIST = 'list',
  GET = 'get',
  WRITE = 'write'
}

export interface FirestoreErrorInfo {
  error: string;
  operationType: OperationType;
  path: string | null;
  authInfo: {
    userId: string | undefined;
    email: string | null | undefined;
    emailVerified: boolean | undefined;
    isAnonymous: boolean | undefined;
  };
}

export function handleFirestoreError(error: unknown, operationType: OperationType, path: string | null): never {
  const errInfo: FirestoreErrorInfo = {
    error: error instanceof Error ? error.message : String(error),
    authInfo: {
      userId: auth.currentUser?.uid,
      email: auth.currentUser?.email,
      emailVerified: auth.currentUser?.emailVerified,
      isAnonymous: auth.currentUser?.isAnonymous
    },
    operationType,
    path
  };
  console.error('Firestore Error:', JSON.stringify(errInfo));
  throw new Error(JSON.stringify(errInfo));
}

// Test connection on boot per Firebase guidelines with safe fallback
export async function testConnection(): Promise<void> {
  try {
    await getDocFromServer(doc(db, 'test', 'connection'));
  } catch (error) {
    if (error instanceof Error && error.message.includes('the client is offline')) {
      console.warn('Firestore client is currently offline.');
    }
  }
}
void testConnection();

// Sign In with Google
export async function signInWithGoogle(): Promise<User | null> {
  try {
    const result = await signInWithPopup(auth, googleProvider);
    const user = result.user;
    if (user) {
      // Save or update user profile document
      await setDoc(
        doc(db, 'users', user.uid),
        {
          uid: user.uid,
          email: user.email || '',
          displayName: user.displayName || 'Streetwear Collector',
          photoURL: user.photoURL || '',
          lastLogin: new Date().toISOString()
        },
        { merge: true }
      );
    }
    return user;
  } catch (err: unknown) {
    console.error('Google Sign-In Error:', err);
    throw err;
  }
}

// Sign Out
export async function signOutUser(): Promise<void> {
  await firebaseSignOut(auth);
}

// Auth State Listener
export function onAuthUserChange(callback: (user: User | null) => void): () => void {
  return onAuthStateChanged(auth, callback);
}

export interface StoredBagItem {
  id: string;
  name: string;
  price: number;
  size: string;
  image: string;
  quantity: number;
  variantId?: number;
}

// Sync Cart / Bag to Firestore
export async function syncCartToFirestore(userId: string, items: StoredBagItem[]): Promise<void> {
  try {
    const cartRef = doc(db, 'users', userId);
    await setDoc(cartRef, { cartItems: items, updatedAt: new Date().toISOString() }, { merge: true });
  } catch (e) {
    console.warn('Could not sync cart to Firestore:', e);
  }
}

// Get Cart from Firestore
export async function getCartFromFirestore(userId: string): Promise<StoredBagItem[] | null> {
  try {
    const cartSnap = await getDoc(doc(db, 'users', userId));
    if (cartSnap.exists() && cartSnap.data().cartItems) {
      return cartSnap.data().cartItems as StoredBagItem[];
    }
  } catch (e) {
    console.warn('Could not fetch cart from Firestore:', e);
  }
  return null;
}

// Sync Wishlist to Firestore
export async function syncWishlistToFirestore(userId: string, itemIds: string[]): Promise<void> {
  try {
    const userRef = doc(db, 'users', userId);
    await setDoc(userRef, { wishlist: itemIds, updatedAt: new Date().toISOString() }, { merge: true });
  } catch (e) {
    console.warn('Could not sync wishlist to Firestore:', e);
  }
}

// Record Order in Firestore
export interface OrderPayload {
  orderId: string;
  userId: string;
  customerEmail: string;
  customerName: string;
  shippingAddress: string;
  city: string;
  postalCode: string;
  country: string;
  paymentMethod: string;
  paymentCardLast4?: string;
  totalAmount: number;
  items: StoredBagItem[];
  status: 'confirmed' | 'processing' | 'quality_check' | 'shipped' | 'delivered';
  currentStage?: 'confirmed' | 'processing' | 'quality_check' | 'shipped' | 'delivered';
  trackingNumber?: string;
  carrier?: string;
  estimatedDelivery?: string;
  emailDispatchedTo?: string;
  emailDispatchStatus?: string;
  createdAt: string;
}

export async function createOrderInFirestore(order: OrderPayload): Promise<void> {
  const trackingNumber = order.trackingNumber || `DHL-ZL-${order.orderId.replace(/[^0-9A-Z]/gi, '').slice(-6) || '849201'}`;
  const estDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toLocaleDateString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric'
  });
  
  const fullOrder: OrderPayload = {
    ...order,
    trackingNumber,
    carrier: order.carrier || 'DHL Express Worldwide',
    estimatedDelivery: order.estimatedDelivery || estDate,
    currentStage: order.currentStage || 'processing',
    emailDispatchedTo: order.emailDispatchedTo || order.customerEmail,
    emailDispatchStatus: order.emailDispatchStatus || 'Sent to Gmail'
  };

  try {
    await setDoc(doc(db, 'orders', order.orderId), {
      ...fullOrder,
      items: JSON.stringify(fullOrder.items)
    });
  } catch (err) {
    console.error('Failed to save order to Firestore:', err);
    throw err;
  }
}

// Fetch User Orders
export async function getUserOrdersFromFirestore(userId: string): Promise<OrderPayload[]> {
  if (!userId || userId === 'guest-shopper') return [];
  try {
    const q = query(collection(db, 'orders'), where('userId', '==', userId));
    const snapshot = await getDocs(q);
    const orders: OrderPayload[] = [];
    snapshot.forEach((d) => {
      const data = d.data();
      orders.push({
        ...data,
        items: typeof data.items === 'string' ? JSON.parse(data.items) : data.items
      } as OrderPayload);
    });
    return orders;
  } catch (e) {
    console.warn('Could not load orders:', e);
    return [];
  }
}

// Look up order by Order ID or Tracking Number
export async function getOrderByIdFromFirestore(orderIdOrTracking: string): Promise<OrderPayload | null> {
  const cleanId = orderIdOrTracking.trim();
  if (!cleanId) return null;
  
  try {
    // First try direct document ID lookup
    const docSnap = await getDoc(doc(db, 'orders', cleanId));
    if (docSnap.exists()) {
      const data = docSnap.data();
      return {
        ...data,
        items: typeof data.items === 'string' ? JSON.parse(data.items) : data.items
      } as OrderPayload;
    }

    // Secondary query by trackingNumber
    const q = query(collection(db, 'orders'), where('trackingNumber', '==', cleanId));
    const querySnap = await getDocs(q);
    if (!querySnap.empty) {
      const data = querySnap.docs[0].data();
      return {
        ...data,
        items: typeof data.items === 'string' ? JSON.parse(data.items) : data.items
      } as OrderPayload;
    }
  } catch (err) {
    console.warn('Could not find order by tracking:', err);
  }
  return null;
}

